-- Migration 028: E-54 PagerDuty/Opsgenie alert integration support.
-- Extends ticket_integrations to accept 'pagerduty' and 'opsgenie' as
-- provider values. The existing CHECK constraint on provider needs updating.
-- Idempotent — safe to re-run.

-- Drop the old CHECK constraint if it exists and recreate with new values.
-- The constraint name was auto-generated by Supabase — we handle both cases.
DO $$
BEGIN
  -- Try dropping by the most common auto-generated name patterns
  BEGIN
    ALTER TABLE public.ticket_integrations DROP CONSTRAINT IF EXISTS ticket_integrations_provider_check;
  EXCEPTION WHEN undefined_object THEN NULL;
  END;

  -- Add (or re-add) the constraint with the expanded set
  BEGIN
    ALTER TABLE public.ticket_integrations
      ADD CONSTRAINT ticket_integrations_provider_check
      CHECK (provider IN ('jira', 'linear', 'pagerduty', 'opsgenie'));
  EXCEPTION WHEN duplicate_object THEN NULL;
  END;
END $$;

-- Opsgenie region (us/eu) — only used when provider = 'opsgenie'
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'ticket_integrations' AND column_name = 'region'
  ) THEN
    ALTER TABLE public.ticket_integrations ADD COLUMN region text;
  END IF;
END $$;
